import React from "react";
import { Link } from "react-router-dom";

export default function Sentiment() {
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        minHeight: "100vh",
        background: "linear-gradient(135deg, #11998e 0%, #38ef7d 100%)",
        color: "#fff",
        padding: "2rem",
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
        textAlign: "center",
      }}
    >
      <h2 style={{ fontSize: "2.5rem", fontWeight: "700", marginBottom: "1rem" }}>
        Sentiment Analysis Results
      </h2>
      <p style={{ fontSize: "1.2rem", opacity: 0.85 }}>
        👉 Your sentiment analysis output will appear here...
      </p>
      <Link to="/" style={{ marginTop: "2rem", textDecoration: "none" }}>
        <button
          style={{
            background: "linear-gradient(135deg, #ffd700 0%, #ffa500 100%)",
            border: "none",
            borderRadius: "30px",
            padding: "12px 28px",
            fontSize: "1.1rem",
            fontWeight: "600",
            color: "#1a1a1a",
            cursor: "pointer",
            boxShadow: "0 4px 15px rgba(255, 165, 0, 0.5)",
            transition: "all 0.3s ease",
            minWidth: "180px",
          }}
          onMouseEnter={(e) => {
            e.target.style.background = "linear-gradient(135deg, #ffa500 0%, #ffd700 100%)";
            e.target.style.color = "#fff";
            e.target.style.boxShadow = "0 6px 20px rgba(255, 140, 0, 0.75)";
          }}
          onMouseLeave={(e) => {
            e.target.style.background = "linear-gradient(135deg, #ffd700 0%, #ffa500 100%)";
            e.target.style.color = "#1a1a1a";
            e.target.style.boxShadow = "0 4px 15px rgba(255, 165, 0, 0.5)";
          }}
        >
          Back
        </button>
      </Link>
    </div>
  );
}
